// Acknowledges a non-emergency POST instead of dropping it silently.
// The false branch used to be empty: the execution ended with no output, so
// there was no audit trail that the alert had been seen and rejected.
const alert = $input.first().json.body || {};
return [{
  json: {
    event: 'emergency_alert_ignored',
    status: 'not_an_emergency',
    userId: alert.userId || null,
    source: alert.source || null,
    reason: alert.reason || 'isEmergency was not true',
    receivedAt: new Date().toISOString()
  }
}];

const expectedSecret = ($env && $env.N8N_WEBHOOK_SECRET) || null;
try {
  const wh = ($('Emergency Webhook').first().json.headers) || {};
  const provided = wh['x-n8n-secret'];
  if (expectedSecret && provided !== expectedSecret) { throw new Error('Unauthorized: bad webhook secret'); }
} catch (e) {
  if (String(e.message).includes('Unauthorized')) throw e;
}

const alert = $('Emergency Webhook').first().json.body || {};
// The hospital lookup may have failed (missing key, timeout): keep the alert.
const mapsResponse = $input.first().json || {};
const hospital = Array.isArray(mapsResponse.results) && mapsResponse.results.length > 0
  ? mapsResponse.results[0]
  : null;

const location = alert.location || {};
const profile = alert.medicalProfile || {};
const hasCoords = location.lat != null && location.lng != null;
const mapsLink = hasCoords
  ? `https://www.google.com/maps?q=${location.lat},${location.lng}`
  : 'Location unavailable';
const hospitalName = hospital?.name || 'Nearest hospital could not be identified';
const hospitalAddress = hospital?.vicinity || hospital?.formatted_address || 'Address unavailable';
const allergies = Array.isArray(profile.allergies) ? profile.allergies.join(', ') : (profile.allergies || 'Not provided');
const conditions = Array.isArray(profile.conditions) ? profile.conditions.join(', ') : (profile.conditions || 'Not provided');
const bloodType = profile.bloodType || 'Not provided';

// The backend sends `emergencyContacts` (array); older callers sent
// `emergencyContact` (object). A WhatsApp send with an undefined number is a
// silent no-op, so both shapes are normalised and a missing phone is surfaced
// rather than dropped.
const contacts = Array.isArray(alert.emergencyContacts)
  ? alert.emergencyContacts
  : (alert.emergencyContact ? [alert.emergencyContact] : []);
const contact = contacts.find((c) => c && (c.phone || c.phoneNumber)) || {};
const recipientPhone = contact.phone || contact.phoneNumber || null;

const whatsappMessage = [
  'EMERGENCY ALERT',
  '',
  `Reason: ${alert.message || 'No user message was provided.'}`,
  'The emergency detector marked this request as critical. The user may not be responding.',
  '',
  `Location: ${mapsLink}`,
  `Nearest hospital: ${hospitalName}`,
  `Hospital address: ${hospitalAddress}`,
  '',
  'Medical profile:',
  `Allergies: ${allergies}`,
  `Conditions: ${conditions}`,
  `Blood type: ${bloodType}`,
  '',
  'Please contact local emergency services immediately if this is an active emergency.'
].join('\n');

return [{
  json: {
    userId: alert.userId || null,
    isEmergency: true,
    source: alert.source || 'classifier',
    emergencyReason: alert.message || null,
    location,
    hasCoords,
    mapsLink,
    nearestHospital: hospital ? { name: hospitalName, address: hospitalAddress, placeId: hospital.place_id || null } : null,
    emergencyContact: contact,
    recipientPhone,
    // Drives the branch below: no phone means the alert must still be logged.
    canNotify: Boolean(recipientPhone),
    medicalProfile: { allergies, conditions, bloodType },
    whatsappMessage
  }
}];

const alert = $('Build Emergency Message').first().json;
const results = $input.all();

// The alert event plus whatever the WhatsApp node produced. `status` used to
// be the literal string 'prepared_for_logging' and the object then went
// nowhere, so an emergency notification was never actually recorded.
const whatsapp = results.find((r) => r.json && (r.json.key || r.json.sid || r.json.status)) || {};

return [{
  json: {
    event: 'emergency_whatsapp_alert',
    status: alert.canNotify ? (whatsapp.json ? 'notified' : 'notify_failed') : 'no_recipient',
    userId: alert.userId,
    source: alert.source,
    isEmergency: true,
    emergencyReason: alert.emergencyReason,
    recipientPhone: alert.recipientPhone,
    emergencyContact: alert.emergencyContact,
    hasCoords: alert.hasCoords,
    nearestHospital: alert.nearestHospital,
    mapsLink: alert.mapsLink,
    whatsappResponse: whatsapp.json || whatsapp,
    processedAt: new Date().toISOString()
  }
}];

const alert = $('Build Emergency Message').first().json;
return [{
  json: {
    event: 'emergency_alert_not_notified',
    status: 'no_recipient_phone',
    userId: alert.userId,
    source: alert.source,
    emergencyReason: alert.emergencyReason,
    mapsLink: alert.mapsLink,
    nearestHospital: alert.nearestHospital,
    note: 'No emergency contact with a phone number on the profile. Add one in the Medical Passport so alerts can be delivered.',
    processedAt: new Date().toISOString()
  }
}];
